<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/connection.php'; require_alumni();$q=trim($_GET['q']??'');$profiles=[];$sql="SELECT u.email,u.first_name,u.middle_name,u.last_name,u.course,u.batch_year,p.city,p.directory_bio,e.company_name,e.job_title FROM users u LEFT JOIN alumni_profiles p ON p.email=u.email LEFT JOIN employment_information e ON e.email=u.email AND e.is_current=1 WHERE COALESCE(u.role,'')<>'admin' AND u.email<>?";if($q!=='')$sql.=" AND (u.first_name LIKE ? OR u.last_name LIKE ? OR u.course LIKE ? OR p.city LIKE ? OR e.company_name LIKE ? OR e.job_title LIKE ?)";$sql.=' ORDER BY u.last_name,u.first_name';$stmt=mysqli_prepare($connection,$sql);if($q!==''){$like="%$q%";mysqli_stmt_bind_param($stmt,'sssssss',$email,$like,$like,$like,$like,$like,$like);}else{$email=$_SESSION['user_email'];mysqli_stmt_bind_param($stmt,'s',$email);}mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r))$profiles[]=$row;mysqli_stmt_close($stmt);$pageTitle='Alumni Directory';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Directory | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><section class="hero-banner"><h2>Alumni Directory</h2><p>Find peers, professional connections, and shared experiences.</p></section><div class="panel search-panel"><form method="get"><input class="input" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search by name, course, city, company, or role"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-search"></i> Search</button></form></div><div class="directory-grid" style="margin-top:22px"><?php foreach($profiles as $p):$name=trim(($p['first_name']??'').' '.($p['middle_name']??'').' '.($p['last_name']??''));?><article class="directory-card"><div class="directory-avatar"><?=htmlspecialchars(strtoupper(substr($name?:'A',0,1)))?></div><h3><?=htmlspecialchars($name?:'Alumni')?></h3><p><?=htmlspecialchars($p['course']?:'Course not provided')?></p><div class="tag-list"><span class="tag"><?=htmlspecialchars($p['batch_year']?:'Batch not provided')?></span><?php if($p['city']):?><span class="tag"><?=htmlspecialchars($p['city'])?></span><?php endif;?></div><?php if($p['job_title']):?><p class="muted"><?=htmlspecialchars($p['job_title'])?> at <?=htmlspecialchars($p['company_name']?:'Company')?></p><?php endif;?><a class="btn btn-primary" href="mailto:<?=htmlspecialchars($p['email'])?>">Contact</a></article><?php endforeach;if(!$profiles):?><div class="panel"><p class="muted">No public alumni profiles found.</p></div><?php endif;?></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
